import React, { useState, useEffect } from 'react';
import { getLogs } from '../services/api';
import { RiskBadge, ActionBadge } from '../components/RiskBadge';
import EventCard from '../components/EventCard';

export default function Logs() {
  const [data, setData]     = useState(null);
  const [loading, setLoading] = useState(true);
  const [filter, setFilter] = useState('all');

  useEffect(() => {
    getLogs(100)
      .then(r => setData(r.data))
      .catch(() => alert('Could not fetch logs.'))
      .finally(() => setLoading(false));
  }, []);

  if (loading) return <div className="flex items-center justify-center h-64 text-gray-500">⏳ Loading logs...</div>;
  if (!data)   return null;

  const { events, stats } = data;
  const filtered = filter === 'all' ? events : events.filter(e => e.action === filter || e.risk === filter);

  return (
    <div className="space-y-6 max-w-5xl">
      <div>
        <h2 className="text-xl font-bold text-gray-800">🗄️ Stored Event Logs</h2>
        <p className="text-sm text-gray-500">All AI decisions saved to the local database — permanent record</p>
      </div>

      {/* Totals */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
        {[
          { label: 'Total Logged', value: stats.total,   color: 'bg-blue-50 border-blue-200 text-blue-700' },
          { label: 'Allowed',      value: stats.allowed, color: 'bg-green-50 border-green-200 text-green-700' },
          { label: 'Blocked',      value: stats.blocked, color: 'bg-red-50 border-red-200 text-red-700' },
          { label: 'Flagged',      value: stats.flagged, color: 'bg-yellow-50 border-yellow-200 text-yellow-700' },
        ].map(s => (
          <div key={s.label} className={`rounded-xl border p-4 ${s.color}`}>
            <div className="text-2xl font-bold">{s.value}</div>
            <div className="text-xs font-medium uppercase mt-1 opacity-70">{s.label}</div>
          </div>
        ))}
      </div>

      {/* Filter pills */}
      <div className="flex gap-2 flex-wrap">
        {['all','blocked','flagged','allowed','critical','high','medium','low'].map(f => (
          <button key={f} onClick={() => setFilter(f)}
            className={`px-3 py-1 rounded-full text-xs font-medium border transition-colors ${
              filter === f ? 'bg-blue-700 text-white border-blue-700' : 'bg-white text-gray-600 border-gray-300 hover:border-blue-400'
            }`}>
            {f.charAt(0).toUpperCase() + f.slice(1)}
          </button>
        ))}
        <span className="text-xs text-gray-400 self-center ml-2">{filtered.length} events</span>
      </div>

      {events.length === 0 ? (
        <div className="bg-white rounded-xl shadow p-12 text-center text-gray-400">
          <div className="text-5xl mb-3">🗄️</div>
          <p className="font-medium">No logs yet</p>
          <p className="text-sm mt-1">Run a simulation or generate a report — events will be saved here automatically.</p>
        </div>
      ) : (
        <div className="space-y-2">
          {filtered.map(e => <EventCard key={e.id} event={e} />)}
        </div>
      )}
    </div>
  );
}
